57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
66	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
67	     */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
70	
71	    /**
72	     * Common address abbreviations expanded to their full form during address normalization.
73	     * Matching is performed per whitespace-separated token on the upper-cased value.
74	     */
75	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
76	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        LocalDate effectiveDate = owner.getRegistrationDate() != null
127	            ? owner.getRegistrationDate() : LocalDate.now();
128	        LocalDate registrationDate = toBusinessDay(effectiveDate);
129	        owner.setRegistrationDate(registrationDate);
130	        long createdToday = this.clinicService.findAllOwners().stream()
131	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
132	            .count();
133	        if (createdToday >= 100) {
134	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
135	        }
136	        String address = normalizeAddress(owner.getAddress());
137	        if (address == null || address.isEmpty()) {
138	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
139	        }
140	        owner.setAddress(address);
141	        String telephone = toE164(owner.getTelephone());
142	        if (telephone == null) {
143	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
144	        }
145	        owner.setTelephone(telephone);
146	        if (owner.getEmail() != null) {
147	            String email = normalizeEmail(owner.getEmail());
148	            if (!EMAIL_PATTERN.matcher(email).matches()) {
149	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
150	            }
151	            owner.setEmail(email);
152	        }
153	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
154	            .anyMatch(existing -> telephone.equals(toE164(existing.getTelephone())));
155	        if (telephoneInUse) {
156	            return new ResponseEntity<>(HttpStatus.CONFLICT);
157	        }
158	        String cityKey = householdKey(owner.getCity());
159	        long cityCount = this.clinicService.findAllOwners().stream()
160	            .filter(existing -> existing.getCity() != null
161	                && cityKey.equals(householdKey(existing.getCity())))
162	            .count();
163	        if (cityCount >= 50) {
164	            return new ResponseEntity<>(HttpStatus.CONFLICT);
165	        }
166	        String lastNameKey = householdKey(owner.getLastName());
167	        String addressKey = householdKey(owner.getAddress());
168	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
170	                && addressKey.equals(householdKey(existing.getAddress())))
171	            .toList();
172	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
173	            String householdId = householdMembers.stream()
174	                .map(Owner::getHouseholdId)
175	                .filter(Objects::nonNull)
176	                .findFirst()
177	                .orElseGet(() -> householdId(owner));
178	            owner.setHouseholdId(householdId);
179	            for (Owner member : householdMembers) {
180	                if (member.getHouseholdId() == null) {
181	                    member.setHouseholdId(householdId);
182	                    this.clinicService.saveOwner(member);
183	                }
184	            }
185	        } else if (!householdMembers.isEmpty()) {
186	            return new ResponseEntity<>(HttpStatus.CONFLICT);
187	        }
188	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
189	        String firstNameKey = householdKey(owner.getFirstName());
190	        String namesakeLastNameKey = householdKey(owner.getLastName());
191	        long namesakeCount = this.clinicService.findAllOwners().stream()
192	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
193	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
194	            .count();
195	        owner.setNamesakeCount((int) namesakeCount);
196	        this.clinicService.saveOwner(owner);
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    /**
204	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
205	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
206	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
207	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
208	     *
209	     * @param telephone the raw telephone value (may be {@code null})
210	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
211	     *         a valid E.164 number
212	     */
213	    private String toE164(String telephone) {
214	        if (telephone == null) {
215	            return null;
216	        }
217	        String trimmed = telephone.trim();
218	        boolean hasCountryCode = trimmed.startsWith("+");
219	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
220	        if (hasCountryCode) {
221	            cleaned = cleaned.substring(1);
222	        }
223	        if (!cleaned.matches("[0-9]+")) {
224	            return null;
225	        }
226	        String digits;
227	        if (hasCountryCode) {
228	            digits = cleaned;
229	        } else {
230	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
231	            digits = "61" + national;
232	        }
233	        if (digits.length() < 8 || digits.length() > 15) {
234	            return null;
235	        }
236	        return "+" + digits;
237	    }
238	
239	    /**
240	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
241	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
242	     *
243	     * @param email the raw email value (must not be {@code null})
244	     * @return the trimmed, lower-cased email
245	     */
246	    private String normalizeEmail(String email) {
247	        return email.trim().toLowerCase(Locale.ROOT);
248	    }
249	
250	    /**
251	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
252	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
253	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
254	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
255	     * normalized form, and every household comparison uses it.
256	     *
257	     * @param address the raw address value (may be {@code null})
258	     * @return the normalized address, or {@code null} if the input was {@code null}
259	     */
260	    private String normalizeAddress(String address) {
261	        if (address == null) {
262	            return null;
263	        }
264	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
265	        if (collapsed.isEmpty()) {
266	            return collapsed;
267	        }
268	        String[] tokens = collapsed.split(" ");
269	        StringBuilder sb = new StringBuilder(collapsed.length());
270	        for (int i = 0; i < tokens.length; i++) {
271	            if (i > 0) {
272	                sb.append(' ');
273	            }
274	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
275	        }
276	        return sb.toString();
277	    }
278	
279	    /**
280	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
281	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
282	     * so that owners are compared case-insensitively with collapsed whitespace.
283	     *
284	     * @param value the raw value (must not be {@code null})
285	     * @return the normalized comparison key
286	     */
287	    private String householdKey(String value) {
288	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
289	    }
290	
291	    /**
292	     * Derives a stable, shared household identifier for the owner's household. The value is a
293	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
294	     * every owner in the same household derives the identical identifier of the form
295	     * {@code 'HH-<12 upper-case hex>'}.
296	     *
297	     * @param owner the owner whose household identifier is derived
298	     * @return the stable household identifier
299	     */
300	    private String householdId(Owner owner) {
301	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
302	        try {
303	            byte[] digest = MessageDigest.getInstance("SHA-256")
304	                .digest(key.getBytes(StandardCharsets.UTF_8));
305	            StringBuilder sb = new StringBuilder(digest.length * 2);
306	            for (byte b : digest) {
307	                sb.append(String.format("%02x", b));
308	            }
309	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
310	        }
311	        catch (java.security.NoSuchAlgorithmException e) {
312	            throw new IllegalStateException("SHA-256 not available", e);
313	        }
314	    }
315	
316	    /**
317	     * Builds the customer code for a newly registered owner in the form
318	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three
319	     * letters of the city, {@code LAST3} the upper-cased first three letters of the last name
320	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
321	     * number of owners already registered in that city (e.g. {@code 'SYD-SMI-0007'}).
322	     *
323	     * @param city     the owner's city
324	     * @param lastName the owner's last name
325	     * @return the assigned customer code
326	     */
327	    private String nextCustomerCode(String city, String lastName) {
328	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
329	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
330	        String cityKey = householdKey(city);
331	        int sequence = (int) this.clinicService.findAllOwners().stream()
332	            .filter(existing -> existing.getCity() != null && cityKey.equals(householdKey(existing.getCity())))
333	            .count() + 1;
334	        return String.format(Locale.ROOT, "%s-%s-%04d", city3, last3, sequence);
335	    }
336	
337	    /**
338	     * Rolls a registration date forward onto a business day. When the given date falls on a
339	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
340	     *
341	     * @param date the effective registration date (must not be {@code null})
342	     * @return the same date if it is a weekday, otherwise the next Monday
343	     */
344	    private LocalDate toBusinessDay(LocalDate date) {
345	        DayOfWeek dayOfWeek = date.getDayOfWeek();
346	        if (dayOfWeek == DayOfWeek.SATURDAY) {
347	            return date.plusDays(2);
348	        }
349	        if (dayOfWeek == DayOfWeek.SUNDAY) {
350	            return date.plusDays(1);
351	        }
352	        return date;
353	    }
354	
355	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
356	    @Override
357	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
358	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
359	        if (currentOwner == null) {
360	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
361	        }
362	        String email = ownerFieldsDto.getEmail();
363	        if (email != null) {
364	            email = normalizeEmail(email);
365	            if (!EMAIL_PATTERN.matcher(email).matches()) {
366	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
367	            }
368	        }
369	        String telephone = toE164(ownerFieldsDto.getTelephone());
370	        if (telephone == null) {
371	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
372	        }
373	        currentOwner.setAddress(ownerFieldsDto.getAddress());
374	        currentOwner.setCity(ownerFieldsDto.getCity());
375	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
376	        currentOwner.setLastName(ownerFieldsDto.getLastName());
377	        currentOwner.setTelephone(telephone);
378	        currentOwner.setEmail(email);
379	        this.clinicService.saveOwner(currentOwner);
380	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
381	    }
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Transactional
385	    @Override
386	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
387	        Owner owner = this.clinicService.findOwnerById(ownerId);
388	        if (owner == null) {
389	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
390	        }
391	        this.clinicService.deleteOwner(owner);
392	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
393	    }
394	
395	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
396	    @Override
397	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
398	        Owner owner = this.clinicService.findOwnerById(ownerId);
399	        if (owner == null) {
400	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
401	        }
402	        HttpHeaders headers = new HttpHeaders();
403	        Pet pet = petMapper.toPet(petFieldsDto);
404	        owner.setId(ownerId);
405	        pet.setOwner(owner);
406	        pet.getType().setName(null);
407	        this.clinicService.savePet(pet);
408	        PetDto petDto = petMapper.toPetDto(pet);
409	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
410	            .buildAndExpand(pet.getId()).toUri());
411	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
412	    }
413	
414	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
415	    @Override
416	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
417	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
418	        if (currentOwner != null) {
419	            Pet currentPet = this.clinicService.findPetById(petId);
420	            if (currentPet != null) {
421	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
422	                currentPet.setName(petFieldsDto.getName());
423	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
424	                this.clinicService.savePet(currentPet);
425	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
426	            }
427	        }
428	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
429	    }
430	
431	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
432	    @Override
433	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
434	        HttpHeaders headers = new HttpHeaders();
435	        Visit visit = visitMapper.toVisit(visitFieldsDto);
436	        Pet pet = new Pet();
437	        pet.setId(petId);
438	        visit.setPet(pet);
439	        this.clinicService.saveVisit(visit);
440	        VisitDto visitDto = visitMapper.toVisitDto(visit);
441	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
442	            .buildAndExpand(visit.getId()).toUri());
443	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
444	    }
445	
446	
447	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
448	    @Override
449	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
450	        Owner owner = this.clinicService.findOwnerById(ownerId);
451	        if (owner != null) {
452	            Pet pet = owner.getPet(petId);
453	            if (pet != null) {
454	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
455	            }
456	        }
457	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
458	    }
459	}
